/**
 * Calculates the nth Fibonacci number using recursion.
 *
 * The Fibonacci sequence is a series where each number is the sum of the two preceding ones,
 * starting from 0 and 1. That is: 0, 1, 1, 2, 3, 5, 8, 13, ...
 *
 * @param n The position in the Fibonacci sequence (non-negative integer)
 * @return The nth Fibonacci number
 *
 * Note: This implementation uses a simple recursive approach. While clear and concise,
 * it has exponential time complexity O(2^n) due to repeated calculations, making it
 * inefficient for large values of n.
 */
int fibonacci(int n) {
    // Base case: The first two Fibonacci numbers are 0 and 1
    // When n is 0 or 1, return n directly
    if (n < 2) {
        return n;
    }

    // Recursive case: Compute the nth Fibonacci number by summing the two previous numbers
    // fibonacci(n-1) gives the (n-1)th Fibonacci number
    // fibonacci(n-2) gives the (n-2)th Fibonacci number
    // Their sum produces the nth Fibonacci number
    return fibonacci(n - 1) + fibonacci(n - 2);
}

