int fibonacci(int n) {
    // Base case: if n is 0 or 1, return n directly
    if (n < 2) {
        return n;
    }

    // Recursively compute fibonacci(n-1) and fibonacci(n-2)
    int previous_fib = fibonacci(n - 1);
    int second_previous_fib = fibonacci(n - 2);

    // Sum the two previous Fibonacci values to get current value
    int current_fib = previous_fib + second_previous_fib;

    return current_fib;
}
